export function groupByStatus(tasks: Task[]): Record<string, Task[]> {
  return tasks.reduce((acc, task) => {
    acc[task.status] = [...(acc[task.status] ?? []), task];
    return acc;
  }, {} as Record<string, Task[]>);
}

async function chargeOnce(key: string, amount: number) {
  const claimed = await store.claim(key);
  if (!claimed) return store.result(key);
  const result = await gateway.charge(amount);
  await store.save(key, result);
  return result;
}

async function readThrough(key: string, load: () => Promise<Value>) {
  const hit = await cache.get(key);
  if (hit !== null) return hit;
  const pending = inflight.get(key) ?? load();
  inflight.set(key, pending);
  try {
    const value = await pending;
    await cache.set(key, value, ttlSeconds);
    return value;
  } finally {
    inflight.delete(key);
  }
}

function TaskList({ state }: TaskListProps) {
  if (state.status === "loading") return <p role="status">Cargando…</p>;
  if (state.status === "error") return <p role="alert">No pudimos cargar.</p>;
  if (state.items.length === 0) return <p>Sin tareas todavía.</p>;
  return <ul>{state.items.map((task) => <li key={task.id}>{task.title}</li>)}</ul>;
}

async function onSubmit(values: FormValues) {
  setErrors({});
  const result = await save(values);
  if (!result.ok) {
    setErrors(result.fieldErrors);
    firstInvalidField.current?.focus();
    return;
  }
  announce("Guardado correctamente");
}

const visibleRows = useMemo(
  () => sortRows(rows, sortKey).slice(start, start + pageSize),
  [rows, sortKey, start, pageSize],
);

def clean(rows):
    valid = []
    rejected = []
    for row in rows:
        if row.get("amount") is None or row["amount"] < 0:
            rejected.append(row)
        else:
            valid.append(row)
    return valid, rejected

def publish_if_valid(df, contract):
    report = contract.validate(df)
    if not report.ok:
        raise QualityGateFailed(report.failures)
    write_table(df, contract.target)
    record_lineage(contract.source, contract.target, report)
